code.code:
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return self.name + '在出声'

class Dog(Animal):
    def speak(self):
        return super().speak() + '：汪！'

class Puppy(Dog):
    def speak(self):
        return '小' + super().speak()

print(Puppy('豆豆').speak())
